package com.interviewcoach.model;
import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="interviews") public class Interview {@Id @GeneratedValue(strategy=GenerationType.IDENTITY)public Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="user_id")public User user;public String role,kind,mode,difficulty,experience;@Column(name="proctor_mode")public String proctorMode;@Column(name="job_description",columnDefinition="text")public String jobDescription;@Column(name="question_limit")public int questionLimit;public String status="ACTIVE";@Column(name="current_question",columnDefinition="text")public String currentQuestion;@Column(columnDefinition="text")public String report;@Column(name="started_at")public Instant startedAt=Instant.now();@Column(name="finished_at")public Instant finishedAt;}
